package com.farika.soundflow;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import android.net.Uri;import android.media.session.*;
/** User-initiated, bounded first-party write. No optimistic heart, no invisible challenge handling. */
public class NotificationLikeService extends Service {
 static final int ID=9;static final String EVENT="com.farika.soundflow.LIKE_CONFIRMED";private AccountWriter writer;private boolean busy,failurePosted;private String owner,id;private boolean liked;
 static Intent command(Context c,Library.Track t,boolean liked){String owner=PlaybackCheckpoint.owner(c);return new Intent(c,NotificationLikeService.class).setAction("SET_LIKE").setData(new Uri.Builder().scheme("volna").authority("like").appendPath(owner).appendPath(t.id()).appendPath(liked?"1":"0").build()).putExtra("owner",owner).putExtra("track",t.id()).putExtra("liked",liked);}
 static PendingIntent pending(Context c,Library.Track t,boolean liked){return PendingIntent.getForegroundService(c,0,command(c,t,liked),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void request(Context c,Library.Track t,boolean liked){if(t!=null&&!t.id().isEmpty())try{c.startForegroundService(command(c,t,liked));}catch(RuntimeException e){NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("account_actions","Действия с SoundCloud",NotificationManager.IMPORTANCE_LOW));nm.notify(ID,new Notification.Builder(c,"account_actions").setSmallIcon(R.drawable.ic_heart_outline).setContentTitle("SoundCloud · Любимое").setContentText("Android не разрешил отправку из уведомления. Повторите из приложения.").setContentIntent(PlaybackNotice.open(c)).setAutoCancel(true).build());}}
 protected AccountWriter createWriter(AccountWriter.Callback callback){return new AccountWriter(getApplicationContext(),callback);}
 private Notification note(String text,boolean ongoing){getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("account_actions","Действия с SoundCloud",NotificationManager.IMPORTANCE_LOW));return new Notification.Builder(this,"account_actions").setSmallIcon(R.drawable.ic_heart_outline).setContentTitle("SoundCloud · Любимое").setContentText(text).setContentIntent(PlaybackNotice.open(this)).setOnlyAlertOnce(true).setOngoing(ongoing).setAutoCancel(!ongoing).build();}
 @Override public int onStartCommand(Intent i,int flags,int startId){if(busy)return START_NOT_STICKY;failurePosted=false;Notification preparing=note("Отправляем изменение…",true);if(Build.VERSION.SDK_INT>=34)startForeground(ID,preparing,ServiceInfo.FOREGROUND_SERVICE_TYPE_SHORT_SERVICE);else if(Build.VERSION.SDK_INT>=29)startForeground(ID,preparing,ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC);else startForeground(ID,preparing);if(i==null||!"SET_LIKE".equals(i.getAction())){finish(false,"Изменение не отправлено");return START_NOT_STICKY;}owner=i.getStringExtra("owner");id=i.getStringExtra("track");liked=i.getBooleanExtra("liked",false);if(owner==null||owner.isEmpty()||!owner.equals(PlaybackCheckpoint.owner(this))||id==null||!id.matches("[0-9]{1,20}")||Session.get(this).isEmpty()){finish(false,"Лайк не отправлен. Откройте приложение и проверьте вход.");return START_NOT_STICKY;}busy=true;writer=createWriter(new AccountWriter.Callback(){public void complete(Intent result){if(!owner.equals(result.getStringExtra("owner"))||!owner.equals(PlaybackCheckpoint.owner(NotificationLikeService.this))||!id.equals(result.getStringExtra("track"))){finish(false,"Аккаунт изменился. Лайк не подтверждён.");return;}new WaveCatalog(NotificationLikeService.this).liked(id,liked);Library lib=new Library(NotificationLikeService.this);for(Library.Track t:lib.tracks)if(id.equals(t.id()))t.liked=liked;lib.save();new OfflineStore(NotificationLikeService.this).updateLiked(id,liked);PlaybackService s=PlaybackService.instance;if(s!=null)s.likeConfirmed(owner,id,liked);else PlaybackNotice.refresh(NotificationLikeService.this);sendBroadcast(new Intent(EVENT).setPackage(getPackageName()).putExtra("owner",owner).putExtra("track",id).putExtra("liked",liked));finish(true,"");}public void failed(int status,String reason,boolean verification){finish(false,"UNKNOWN_OUTCOME".equals(reason)?"Результат неизвестен. Проверьте Любимое перед повтором.":verification?"SoundCloud требует проверку. Откройте приложение.":"Лайк не подтверждён SoundCloud"+(status>0?" (HTTP "+status+")":"")+". Откройте приложение.");}});try{if(!writer.submit(liked?"LIKE":"UNLIKE",id,"",""))finish(false,"Изменение не отправлено. Повторите из приложения.");}catch(RuntimeException e){finish(false,"Не удалось открыть транспорт SoundCloud. Повторите из приложения.");}return START_NOT_STICKY;}
 private void finish(boolean ok,String message){busy=false;if(writer!=null){writer.close();writer=null;}stopForeground(STOP_FOREGROUND_REMOVE);if(!ok){failurePosted=true;getSystemService(NotificationManager.class).notify(ID,note(message,false));}stopSelf();}
 @Override public void onTimeout(int startId){finish(false,"Сервис остановил ожидание. Результат неизвестен: проверьте Любимое.");}
 @Override public void onDestroy(){if(writer!=null)writer.close();writer=null;busy=false;stopForeground(failurePosted?STOP_FOREGROUND_DETACH:STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
